const diagnostics=[{"id":1,"pattern":"High activity + low connect rate","diagnosis":"List/data quality, channel selection, timing, deliverability, or territory issue","action":"Audit data source, segmentation, contactability, and channel mix before coaching call volume."},{"id":2,"pattern":"Healthy connect rate + low conversation rate","diagnosis":"Weak opener, poor relevance, fear/hesitation, brush-off handling","action":"Coach first 30 seconds; inspect call clips and message relevance."},{"id":3,"pattern":"Healthy conversations + low meetings booked","diagnosis":"Weak value proposition, unclear ask, poor qualification, or low confidence closing for next step","action":"Coach transition-to-next-step and outcome framing."},{"id":4,"pattern":"High meeting volume + low show rate","diagnosis":"Weak confirmation, low perceived value, poor qualification, calendar delay","action":"Improve confirmation sequence, meeting purpose, and scheduling discipline."},{"id":5,"pattern":"High show rate + low qualified-meeting rate","diagnosis":"Targeting/ICP mismatch or weak pre-qualification","action":"Tighten qualification and SDR/AE acceptance criteria."},{"id":6,"pattern":"Qualified meetings + low opportunity conversion","diagnosis":"Discovery/handoff failure, inconsistent opportunity definition","action":"Inspect discovery notes, handoff completeness, stage-entry criteria."},{"id":7,"pattern":"High pipeline created + low win rate","diagnosis":"Poor opportunity quality, weak discovery, weak differentiation, or late-stage execution","action":"Segment by source, stage, rep, and loss reason; coach deal quality not volume."},{"id":8,"pattern":"Stage 1 to 2 healthy + Stage 2 to 3 weak","diagnosis":"Discovery and problem definition are not strong enough","action":"Review quantified pain, stakeholder map, decision criteria, next steps."},{"id":9,"pattern":"Demo volume high + demo conversion falling","diagnosis":"Generic demos, feature dumping, weak tailoring or value linkage","action":"Score demo tailoring and buyer engagement."},{"id":10,"pattern":"Days in stage rising + activity still high","diagnosis":"Busywork without buyer commitment; hidden objection or missing stakeholder","action":"Require mutual next step and inspect buyer actions, not seller touches."},{"id":11,"pattern":"Forecast volatility rising","diagnosis":"Weak deal inspection, stale close dates, sandbagging, optimism, or CRM hygiene","action":"Tighten forecast cadence and evidence-based commit criteria."},{"id":12,"pattern":"Close-date changes rising + next-step coverage falling","diagnosis":"Pipeline slippage risk","action":"Trigger deal review before forecast call."},{"id":13,"pattern":"Discount rate rising + win rate flat","diagnosis":"Weak value articulation or competitive pressure","action":"Inspect value proof and negotiation behavior."},{"id":14,"pattern":"Deal size falling + number of deals rising","diagnosis":"Mix shift, discounting, or lower-value segments","action":"Segment by ICP/product/channel before interpreting productivity."},{"id":15,"pattern":"Win rate rising + pipeline coverage falling","diagnosis":"Short-term success masking future pipeline risk","action":"Protect prospecting/self-source time."},{"id":16,"pattern":"Call quality improving + business outcomes flat","diagnosis":"Skill may not be bottleneck; territory, product, pricing, ICP, or market may be limiting","action":"Do not prescribe more training; inspect system/market constraints."},{"id":17,"pattern":"Business outcomes improving + call quality flat","diagnosis":"Market tailwind, lead quality, pricing, or luck may be masking skill risk","action":"Avoid declaring training success; validate with controlled cohorts."},{"id":18,"pattern":"Training completion high + live behavior flat","diagnosis":"Knowledge transfer failure","action":"Increase practice, manager reinforcement, observation, and workflow prompts."},{"id":19,"pattern":"Assessment scores high + call scores low","diagnosis":"Test knowledge not transferring to execution","action":"Use scenario practice and live-call coaching."},{"id":20,"pattern":"Training adoption low + manager coaching low","diagnosis":"Manager reinforcement bottleneck","action":"Intervene with managers before adding content."},{"id":21,"pattern":"Manager coaching volume high + rep skill delta low","diagnosis":"Coaching quality problem","action":"Score coaching conversations and action specificity."},{"id":22,"pattern":"Manager 1:1 adherence low + team variance rising","diagnosis":"Reactive management / capacity risk","action":"Protect cadence and reduce admin load."},{"id":23,"pattern":"New-hire course completion high + TTFM slow","diagnosis":"Process/access/lead allocation issue more likely than learning issue","action":"Check systems access, lead flow, calendar opportunities, territory."},{"id":24,"pattern":"TTFM healthy + TTFQ slow","diagnosis":"Reps can start activity but struggle to qualify/create pipeline","action":"Coach discovery and qualification."},{"id":25,"pattern":"TTFQ healthy + time to first deal slow","diagnosis":"Late-stage skill, deal quality, product, pricing, or sales-cycle issue","action":"Inspect stage conversions and first-deal support."},{"id":26,"pattern":"Content searches high + findability low","diagnosis":"Taxonomy/tagging/search-quality problem","action":"Fix metadata and recommendation logic."},{"id":27,"pattern":"Content usage high + stage conversion unchanged","diagnosis":"Content may be used at wrong moment or is low impact","action":"Measure asset usage by stage and outcome, not downloads."},{"id":28,"pattern":"Recommendation CTR high + save/use low","diagnosis":"Click curiosity without utility","action":"Inspect recommendation relevance and content quality."},{"id":29,"pattern":"AI coaching acceptance high + re-score improvement low","diagnosis":"Recommendations are acknowledged but not effective","action":"Review action quality and coaching specificity."},{"id":30,"pattern":"AI scores improve + manager review coverage low","diagnosis":"AI can detect patterns but human reinforcement is missing","action":"Route high-priority changes into manager workflow."},{"id":31,"pattern":"CRM completeness rises + forecast accuracy flat","diagnosis":"Fields are being filled but not with decision-quality evidence","action":"Audit quality, not completion."},{"id":32,"pattern":"Stale opportunities fall + stage regression rises","diagnosis":"Reps may be advancing or cleaning deals aggressively","action":"Check exit criteria and closed-lost hygiene."},{"id":33,"pattern":"Renewal usage drops + sentiment weakens","diagnosis":"Early churn risk","action":"Trigger adoption and executive-value intervention."},{"id":34,"pattern":"Champion leaves + multithreading is low","diagnosis":"High relationship concentration risk","action":"Re-map power immediately."},{"id":35,"pattern":"No success plan + renewal within 120 days","diagnosis":"Value proof risk","action":"Create success plan and executive alignment."},{"id":36,"pattern":"Strong product adoption + no expansion hypothesis","diagnosis":"Missed growth opportunity","action":"Trigger whitespace/account planning."},{"id":37,"pattern":"Expansion activity high + NRR flat","diagnosis":"Poor opportunity quality or value positioning","action":"Inspect expansion conversion and deal size."},{"id":38,"pattern":"Partner certification high + co-sell opportunities low","diagnosis":"Learning not translating to activation","action":"Add joint account planning and first-opportunity milestone."},{"id":39,"pattern":"Partner pipeline high + win rate low","diagnosis":"Partner-sourced opportunity quality or co-sell execution problem","action":"Segment by partner and inspect qualification/coaching."},{"id":40,"pattern":"Executive sponsorship high + adoption low","diagnosis":"Change design/workflow problem rather than leadership visibility","action":"Reduce friction and embed behavior into existing work."},{"id":41,"pattern":"Tool logins high + workflow completion low","diagnosis":"Vanity adoption","action":"Track task completion and business outcome, not access."},{"id":42,"pattern":"Dashboard views high + decisions/actions low","diagnosis":"Analytics consumption without operating change","action":"Instrument action taken, owner, and follow-through."}];

